import { createContext, useContext } from 'react';

import type { TabsContextValue } from './Tabs.types';

export const TabsContext = createContext<TabsContextValue | null>(null);

export function useTabsContext(): TabsContextValue {
  const context = useContext(TabsContext);
  if (!context) {
    throw new Error('Tabs compound components must be used within a Tabs component');
  }
  return context;
}

import {
  forwardRef,
  memo,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from 'react';

import { useControllableState } from '../../hooks/useControllableState/useControllableState';
import { cn } from '../../utils';

import { TabsContext, useTabsContext } from './Tabs.context';
import { useTabsKeyboard } from './useTabsKeyboard';
import { useTabsScroll } from './useTabsScroll';

import type {
  TabItem,
  TabListProps,
  TabPanelProps,
  TabProps,
  TabsContextValue,
  TabsProps,
} from './Tabs.types';

import './Tabs.scroll.css';

// =============================================================================
// Helpers
// =============================================================================

/**
 * Type guard for extra prop with left/right slots.
 * Uses Reflect.get to avoid unsafe bracket-notation property access.
 */
function isExtraSlots(value: unknown): value is { left?: ReactNode; right?: ReactNode } {
  if (value === null || value === undefined || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  // React elements have $$typeof — those are simple ReactNode extra content
  if (Reflect.get(value as object, '$$typeof') !== undefined) {
    return false;
  }
  return (
    Reflect.get(value as object, 'left') !== undefined ||
    Reflect.get(value as object, 'right') !== undefined
  );
}

// =============================================================================
// TabList Component
// =============================================================================

/**
 * TabList component - container for Tab buttons
 *
 * @see https://getbootstrap.com/docs/5.3/components/navs-tabs/
 */
export const TabList = memo(
  forwardRef<HTMLDivElement, TabListProps>(function TabList(
    { children, className = '', style, 'aria-label': ariaLabel, extra, scrollable = false },
    ref
  ) {
    const {
      orientation,
      variant,
      activeTab,
      tabs,
      baseId,
      activationMode,
      focusedTab,
      setActiveTab,
      setFocusedTab,
      onTabAdd,
    } = useTabsContext();

    const handleKeyDown = useTabsKeyboard({
      tabs,
      activeTab,
      orientation,
      activationMode,
      setActiveTab,
      setFocusedTab,
      baseId,
      focusedTab,
    });

    const {
      containerRef: scrollRef,
      canScrollStart,
      canScrollEnd,
      scrollToStart,
      scrollToEnd,
    } = useTabsScroll({ enabled: scrollable, orientation });

    const navClasses = cn(
      'nav',
      variant === 'tabs' && 'nav-tabs',
      variant === 'pills' && 'nav-pills',
      variant === 'underline' && 'nav-underline',
      orientation === 'vertical' && 'flex-column',
      className
    );

    const extraSlots = isExtraSlots(extra) ? extra : undefined;
    const leftExtra = extraSlots?.left;
    const rightExtra = extraSlots?.right;
    const simpleExtra = !extraSlots ? (extra as ReactNode) : undefined;

    // Keyboard events bubble from focused tab buttons — tablist itself doesn't need tabIndex
    const tabListContent = (
      <div
        ref={scrollable ? scrollRef : ref}
        role="tablist"
        aria-label={ariaLabel}
        aria-orientation={orientation}
        className={cn(navClasses, scrollable && 'dsai-tabs-scroll-inner')}
        style={style}
        tabIndex={-1}
        onKeyDown={handleKeyDown}
      >
        {children}
        {onTabAdd && (
          <button
            type="button"
            className={cn('nav-link', 'dsai-tabs-add-btn')}
            onClick={onTabAdd}
            aria-label="Add tab"
            tabIndex={-1}
          >
            +
          </button>
        )}
      </div>
    );

    if (scrollable) {
      return (
        <div ref={ref} className="dsai-tabs-scroll-container d-flex align-items-center">
          {leftExtra && <div className="dsai-tabs-extra-left">{leftExtra}</div>}
          <button
            type="button"
            className="dsai-tabs-scroll-btn dsai-tabs-scroll-btn-start"
            onClick={scrollToStart}
            disabled={!canScrollStart}
            aria-label="Scroll tabs back"
            tabIndex={-1}
          />
          {tabListContent}
          <button
            type="button"
            className="dsai-tabs-scroll-btn dsai-tabs-scroll-btn-end"
            onClick={scrollToEnd}
            disabled={!canScrollEnd}
            aria-label="Scroll tabs forward"
            tabIndex={-1}
          />
          {(rightExtra || simpleExtra) && (
            <div className="dsai-tabs-extra-right">{rightExtra ?? simpleExtra}</div>
          )}
        </div>
      );
    }

    if (extra) {
      return (
        <div ref={ref} className="d-flex align-items-center">
          {leftExtra && <div className="dsai-tabs-extra-left">{leftExtra}</div>}
          {tabListContent}
          {(rightExtra || simpleExtra) && (
            <div className="dsai-tabs-extra-right ms-auto">{rightExtra ?? simpleExtra}</div>
          )}
        </div>
      );
    }

    return tabListContent;
  })
);

TabList.displayName = 'TabList';

// =============================================================================
// Tab Component
// =============================================================================

/**
 * Tab component - individual tab button
 *
 * @see https://getbootstrap.com/docs/5.3/components/navs-tabs/
 */
export const Tab = memo(
  forwardRef<HTMLButtonElement, TabProps>(function Tab(
    { id, children, icon, disabled = false, className = '', style, closable = false },
    ref
  ) {
    const {
      activeTab,
      setActiveTab,
      baseId,
      registerTab,
      unregisterTab,
      focusedTab,
      activationMode,
      onTabClose,
    } = useTabsContext();

    useEffect(() => {
      if (!disabled) {
        registerTab(id);
      }
      return () => {
        unregisterTab(id);
      };
    }, [id, disabled, registerTab, unregisterTab]);

    const isActive = activeTab === id;
    const isFocused = focusedTab === id;
    const tabId = `${baseId}-tab-${id}`;
    const panelId = `${baseId}-panel-${id}`;

    const handleClick = (): void => {
      if (!disabled) {
        setActiveTab(id);
      }
    };

    const handleClose = (e: React.MouseEvent): void => {
      e.stopPropagation();
      onTabClose?.(id);
    };

    const buttonClasses = cn(
      'nav-link',
      isActive && 'active',
      disabled && 'disabled',
      closable && 'dsai-tabs-closable',
      className
    );

    // When closable with onTabClose, wrap in a div to avoid nesting
    // interactive elements (invalid HTML: button inside button)
    if (closable && onTabClose) {
      return (
        <div className={cn('nav-item', 'd-inline-flex', 'align-items-center')}>
          <button
            ref={ref}
            type="button"
            role="tab"
            id={tabId}
            aria-selected={isActive}
            aria-controls={panelId}
            aria-disabled={disabled || undefined}
            tabIndex={isActive || (activationMode === 'manual' && isFocused) ? 0 : -1}
            disabled={disabled}
            className={buttonClasses}
            style={style}
            data-state={isActive ? 'active' : 'inactive'}
            onClick={handleClick}
          >
            {icon && <span className="me-2">{icon}</span>}
            {children}
          </button>
          <button
            type="button"
            className="btn-close btn-close-sm ms-1"
            aria-label={`Close ${typeof children === 'string' ? children : 'tab'}`}
            onClick={handleClose}
            tabIndex={-1}
          />
        </div>
      );
    }

    // Non-closable tabs — no wrapper needed
    return (
      <button
        ref={ref}
        type="button"
        role="tab"
        id={tabId}
        aria-selected={isActive}
        aria-controls={panelId}
        aria-disabled={disabled || undefined}
        tabIndex={isActive || (activationMode === 'manual' && isFocused) ? 0 : -1}
        disabled={disabled}
        className={buttonClasses}
        style={style}
        data-state={isActive ? 'active' : 'inactive'}
        onClick={handleClick}
      >
        {icon && <span className="me-2">{icon}</span>}
        {children}
      </button>
    );
  })
);

Tab.displayName = 'Tab';

// =============================================================================
// TabPanel Component
// =============================================================================

/**
 * TabPanel component - content panel for a tab
 *
 * @see https://getbootstrap.com/docs/5.3/components/navs-tabs/
 */
export const TabPanel = memo(
  forwardRef<HTMLDivElement, TabPanelProps>(function TabPanel(
    { id, children, className = '', style, keepMounted = false },
    ref
  ) {
    const { activeTab, baseId, lazyMount, unmountOnExit, mountedTabs } = useTabsContext();

    const isActive = activeTab === id;
    const hasBeenMounted = mountedTabs.has(id);
    const tabId = `${baseId}-tab-${id}`;
    const panelId = `${baseId}-panel-${id}`;

    // Determine whether to render
    const shouldRender = (() => {
      if (isActive) {
        return true;
      }
      if (keepMounted) {
        return true;
      }
      if (unmountOnExit) {
        return false;
      }
      if (lazyMount && !hasBeenMounted) {
        return false;
      }
      return true;
    })();

    if (!shouldRender) {
      return null;
    }

    const panelClasses = cn('tab-pane', 'fade', isActive && 'show active', className);

    return (
      <div
        ref={ref}
        role="tabpanel"
        id={panelId}
        aria-labelledby={tabId}
        tabIndex={0}
        className={panelClasses}
        style={style}
        hidden={!isActive}
        data-state={isActive ? 'active' : 'inactive'}
      >
        {children}
      </div>
    );
  })
);

TabPanel.displayName = 'TabPanel';

// =============================================================================
// Tabs Container Component
// =============================================================================

/**
 * Tabs component - accessible tabbed interface
 *
 * @see https://getbootstrap.com/docs/5.3/components/navs-tabs/
 */
export const Tabs = memo(
  forwardRef<HTMLDivElement, TabsProps>(function Tabs(
    {
      items,
      children,
      activeTab: controlledActiveTab,
      defaultActiveTab,
      onTabChange,
      orientation = 'horizontal',
      variant = 'tabs',
      fill = false,
      justified = false,
      className = '',
      style,
      id: providedId,
      activationMode = 'automatic',
      lazyMount = false,
      unmountOnExit = false,
      onTabClose,
      onTabAdd,
    },
    ref
  ) {
    const generatedId = useId();
    const baseId = providedId ?? generatedId;

    // Determine default tab
    const defaultTab =
      defaultActiveTab ?? (items && items.length > 0 && items[0] ? items[0].id : '');

    const [activeTab, setActiveTab] = useControllableState<string>({
      value: controlledActiveTab,
      defaultValue: defaultTab,
      onChange: onTabChange,
    });

    // Tab registration for keyboard navigation
    const [registeredTabs, setRegisteredTabs] = useState<string[]>([]);

    // Track which tabs have been mounted (for lazyMount)
    const mountedTabsRef = useRef<Set<string>>(new Set(activeTab ? [activeTab] : []));
    const mountedTabs = mountedTabsRef.current;

    // Track focused tab (for manual activation mode)
    const [focusedTab, setFocusedTab] = useState<string | null>(null);

    // Update mountedTabs when activeTab changes
    const prevActiveTabRef = useRef(activeTab);
    useEffect(() => {
      if (activeTab !== prevActiveTabRef.current) {
        prevActiveTabRef.current = activeTab;
        if (activeTab) {
          mountedTabsRef.current.add(activeTab);
        }
      }
    }, [activeTab]);

    const registerTab = useCallback((tabId: string) => {
      setRegisteredTabs((prev) => (prev.includes(tabId) ? prev : [...prev, tabId]));
    }, []);

    const unregisterTab = useCallback((tabId: string) => {
      setRegisteredTabs((prev) => prev.filter((t) => t !== tabId));
    }, []);

    // Build tabs list from items or registered
    const tabs = useMemo(() => {
      if (items) {
        return items.filter((item) => !item.disabled).map((item) => item.id);
      }
      return registeredTabs;
    }, [items, registeredTabs]);

    // Context value
    const contextValue = useMemo<TabsContextValue>(
      () => ({
        activeTab,
        setActiveTab,
        orientation,
        variant,
        baseId,
        registerTab,
        unregisterTab,
        tabs,
        activationMode,
        focusedTab,
        setFocusedTab,
        lazyMount,
        unmountOnExit,
        mountedTabs,
        onTabClose,
        onTabAdd,
      }),
      // mountedTabs is a stable ref (mountedTabsRef.current) — not included in deps.
      // TabPanel re-renders when activeTab changes, which is when mountedTabs gains entries.
      // eslint-disable-next-line react-hooks/exhaustive-deps
      [
        activeTab,
        setActiveTab,
        orientation,
        variant,
        baseId,
        registerTab,
        unregisterTab,
        tabs,
        activationMode,
        focusedTab,
        setFocusedTab,
        lazyMount,
        unmountOnExit,
        onTabClose,
        onTabAdd,
      ]
    );

    const wrapperClasses = cn(orientation === 'vertical' && 'd-flex', className);

    // Items mode: render using compound components internally
    const renderWithItems = (): ReactNode => {
      if (!items || items.length === 0) {
        return null;
      }

      return (
        <>
          <TabList
            aria-label="Tabs"
            className={cn(
              fill && 'nav-fill',
              justified && 'nav-justified',
              orientation === 'vertical' && 'me-3'
            )}
          >
            {items.map((item) => (
              <Tab
                key={item.id}
                id={item.id}
                icon={item.icon}
                disabled={item.disabled}
                closable={item.closable}
              >
                {item.label}
              </Tab>
            ))}
          </TabList>
          <div className="tab-content">
            {items.map((item) => (
              <TabPanel key={item.id} id={item.id}>
                {item.content}
              </TabPanel>
            ))}
          </div>
        </>
      );
    };

    return (
      <TabsContext.Provider value={contextValue}>
        <div ref={ref} className={wrapperClasses} style={style} id={providedId}>
          {items ? renderWithItems() : children}
        </div>
      </TabsContext.Provider>
    );
  })
);

Tabs.displayName = 'Tabs';

// =============================================================================
// Exports
// =============================================================================

export type { TabItem, TabListProps, TabPanelProps, TabProps, TabsProps };

import type { CSSProperties, ReactNode } from 'react';

/**
 * Tab orientation
 */
export type TabsOrientation = 'horizontal' | 'vertical';

/**
 * Tab variant styling
 */
export type TabsVariant = 'underline' | 'pills' | 'tabs';

/**
 * Keyboard activation mode
 * - 'automatic': tab activates on focus (arrow key moves focus and selects)
 * - 'manual': arrow keys move focus only, Enter/Space activates
 */
export type TabsActivationMode = 'automatic' | 'manual';

/**
 * Tab item configuration
 */
export interface TabItem {
  /**
   * Unique identifier for the tab
   */
  id: string;

  /**
   * Tab label
   */
  label: ReactNode;

  /**
   * Tab panel content
   */
  content: ReactNode;

  /**
   * Icon to display before the label
   */
  icon?: ReactNode;

  /**
   * Whether the tab is disabled
   * @default false
   */
  disabled?: boolean;

  /**
   * Whether this tab can be closed/removed
   * @default false
   */
  closable?: boolean;
}

/**
 * Tabs container props
 */
export interface TabsProps {
  /**
   * Tab items to render
   */
  items?: TabItem[];

  /**
   * Children (alternative to items prop for compound component usage)
   */
  children?: ReactNode;

  /**
   * Currently active tab ID (controlled)
   */
  activeTab?: string;

  /**
   * Default active tab ID (uncontrolled)
   */
  defaultActiveTab?: string;

  /**
   * Callback when active tab changes
   */
  onTabChange?: (tabId: string) => void;

  /**
   * Tab orientation
   * @default 'horizontal'
   */
  orientation?: TabsOrientation;

  /**
   * Tab variant styling
   * @default 'tabs'
   */
  variant?: TabsVariant;

  /**
   * Fill available width
   * @default false
   */
  fill?: boolean;

  /**
   * Justify tabs evenly
   * @default false
   */
  justified?: boolean;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * ID attribute
   */
  id?: string;

  /**
   * Keyboard activation mode
   * - 'automatic': tab activates on arrow key focus (default, current behavior)
   * - 'manual': arrow keys move focus only, Enter/Space to activate
   * @default 'automatic'
   */
  activationMode?: TabsActivationMode;

  /**
   * Lazy mount tab panels — only render when first activated
   * @default false
   */
  lazyMount?: boolean;

  /**
   * Unmount tab panels when they become inactive
   * @default false
   */
  unmountOnExit?: boolean;

  /**
   * Called when a closable tab's close button is clicked
   */
  onTabClose?: (tabId: string) => void;

  /**
   * Called when the add button is clicked (enables add button in tab list)
   */
  onTabAdd?: () => void;
}

/**
 * TabList props
 */
export interface TabListProps {
  /**
   * Tab buttons as children
   */
  children: ReactNode;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * Accessible label for the tab list
   */
  'aria-label'?: string;

  /**
   * Extra content rendered alongside the tab list
   * Can be a ReactNode or { left?: ReactNode; right?: ReactNode }
   */
  extra?: ReactNode | { left?: ReactNode; right?: ReactNode };

  /**
   * Enable horizontal scrolling when tabs overflow
   * @default false
   */
  scrollable?: boolean;
}

/**
 * Tab (button) props
 */
export interface TabProps {
  /**
   * Unique identifier for the tab
   */
  id: string;

  /**
   * Tab label content
   */
  children: ReactNode;

  /**
   * Icon to display before the label
   */
  icon?: ReactNode;

  /**
   * Whether the tab is disabled
   * @default false
   */
  disabled?: boolean;

  /**
   * Whether this tab can be closed
   * @default false
   */
  closable?: boolean;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;
}

/**
 * TabPanel props
 */
export interface TabPanelProps {
  /**
   * ID matching the corresponding Tab
   */
  id: string;

  /**
   * Panel content
   */
  children: ReactNode;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * Keep panel mounted when inactive (for preserving state)
   * @default false
   */
  keepMounted?: boolean;
}

/**
 * Internal context for Tabs
 */
export interface TabsContextValue {
  activeTab: string;
  setActiveTab: (id: string) => void;
  orientation: TabsOrientation;
  variant: TabsVariant;
  baseId: string;
  registerTab: (id: string) => void;
  unregisterTab: (id: string) => void;
  tabs: string[];
  activationMode: TabsActivationMode;
  focusedTab: string | null;
  setFocusedTab: (id: string | null) => void;
  lazyMount: boolean;
  unmountOnExit: boolean;
  mountedTabs: Set<string>;
  onTabClose?: (tabId: string) => void;
  onTabAdd?: () => void;
}

import { type KeyboardEvent, useCallback } from 'react';

import type { TabsActivationMode, TabsOrientation } from './Tabs.types';

/** Safe array element access without triggering security/detect-object-injection */
function getTabAtIndex(list: readonly string[], index: number): string | undefined {
  if (index < 0 || index >= list.length) {
    return undefined;
  }
  let i = 0;
  for (const item of list) {
    if (i === index) {
      return item;
    }
    i += 1;
  }
  return undefined;
}

export interface UseTabsKeyboardOptions {
  tabs: string[];
  activeTab: string;
  orientation: TabsOrientation;
  activationMode: TabsActivationMode;
  setActiveTab: (id: string) => void;
  setFocusedTab: (id: string | null) => void;
  baseId: string;
  focusedTab?: string | null;
}

export function useTabsKeyboard({
  tabs,
  activeTab,
  orientation,
  activationMode,
  setActiveTab,
  setFocusedTab,
  baseId,
  focusedTab,
}: UseTabsKeyboardOptions): (e: KeyboardEvent) => void {
  return useCallback(
    (e: KeyboardEvent): void => {
      if (tabs.length === 0) {
        return;
      }

      const currentTab = focusedTab ?? activeTab;
      const currentIndex = tabs.indexOf(currentTab);
      if (currentIndex === -1) {
        return;
      }

      const isHorizontal = orientation === 'horizontal';
      const prevKey = isHorizontal ? 'ArrowLeft' : 'ArrowUp';
      const nextKey = isHorizontal ? 'ArrowRight' : 'ArrowDown';

      let newIndex = currentIndex;
      let handled = false;

      switch (e.key) {
        case prevKey:
          newIndex = currentIndex > 0 ? currentIndex - 1 : tabs.length - 1;
          handled = true;
          break;
        case nextKey:
          newIndex = currentIndex < tabs.length - 1 ? currentIndex + 1 : 0;
          handled = true;
          break;
        case 'Home':
          newIndex = 0;
          handled = true;
          break;
        case 'End':
          newIndex = tabs.length - 1;
          handled = true;
          break;
        case 'Enter':
        case ' ':
          if (activationMode === 'manual' && focusedTab) {
            e.preventDefault();
            setActiveTab(focusedTab);
          }
          return;
        default:
          return;
      }

      if (!handled) {
        return;
      }

      e.preventDefault();

      const newTabId = getTabAtIndex(tabs, newIndex);
      if (!newTabId) {
        return;
      }

      if (activationMode === 'manual') {
        setFocusedTab(newTabId);
      } else {
        setActiveTab(newTabId);
      }

      // Focus the target tab button
      const tabButton = document.getElementById(`${baseId}-tab-${newTabId}`);
      tabButton?.focus();
    },
    [tabs, activeTab, orientation, activationMode, setActiveTab, setFocusedTab, baseId, focusedTab]
  );
}

import { type RefObject, useCallback, useEffect, useRef, useState } from 'react';

import type { TabsOrientation } from './Tabs.types';

const SCROLL_AMOUNT = 200;

export interface UseTabsScrollOptions {
  enabled: boolean;
  orientation: TabsOrientation;
}

export interface UseTabsScrollReturn {
  containerRef: RefObject<HTMLDivElement | null>;
  canScrollStart: boolean;
  canScrollEnd: boolean;
  scrollToStart: () => void;
  scrollToEnd: () => void;
}

export function useTabsScroll({
  enabled,
  orientation,
}: UseTabsScrollOptions): UseTabsScrollReturn {
  const containerRef = useRef<HTMLDivElement>(null);
  const [canScrollStart, setCanScrollStart] = useState(false);
  const [canScrollEnd, setCanScrollEnd] = useState(false);

  const isHorizontal = orientation === 'horizontal';

  const updateScrollState = useCallback(() => {
    const container = containerRef.current;
    if (!container || !enabled) {
      setCanScrollStart(false);
      setCanScrollEnd(false);
      return;
    }

    if (isHorizontal) {
      setCanScrollStart(container.scrollLeft > 0);
      setCanScrollEnd(
        container.scrollLeft < container.scrollWidth - container.clientWidth - 1
      );
    } else {
      setCanScrollStart(container.scrollTop > 0);
      setCanScrollEnd(
        container.scrollTop < container.scrollHeight - container.clientHeight - 1
      );
    }
  }, [enabled, isHorizontal]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || !enabled) {
      return;
    }

    // Defer initial measurement to avoid synchronous setState in effect
    const rafId = requestAnimationFrame(updateScrollState);

    container.addEventListener('scroll', updateScrollState, { passive: true });

    const observer = new ResizeObserver(updateScrollState);
    observer.observe(container);

    return () => {
      cancelAnimationFrame(rafId);
      container.removeEventListener('scroll', updateScrollState);
      observer.disconnect();
    };
  }, [enabled, updateScrollState]);

  const scrollToStart = useCallback(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    if (isHorizontal) {
      container.scrollBy({ left: -SCROLL_AMOUNT, behavior: 'smooth' });
    } else {
      container.scrollBy({ top: -SCROLL_AMOUNT, behavior: 'smooth' });
    }
  }, [isHorizontal]);

  const scrollToEnd = useCallback(() => {
    const container = containerRef.current;
    if (!container) {
      return;
    }

    if (isHorizontal) {
      container.scrollBy({ left: SCROLL_AMOUNT, behavior: 'smooth' });
    } else {
      container.scrollBy({ top: SCROLL_AMOUNT, behavior: 'smooth' });
    }
  }, [isHorizontal]);

  return {
    containerRef,
    canScrollStart,
    canScrollEnd,
    scrollToStart,
    scrollToEnd,
  };
}
